example_item.example_item_data:
schema = protobuf.load([modulepath('protobuf'), '/tests/data/sensor_stream.proto']);
bytes = protobuf.descriptor(schema);
filename = [tempdir(), 'sensor_stream.binpb'];
fid = fopen(filename, 'w');
fwrite(fid, bytes, 'uint8');
fclose(fid);
schema2 = protobuf.load(filename);
schema2.Messages
delete(filename);
